        "Toca para cargar sus colores en la personalización de arriba",
      "fd.themePresetRedLight": "Rojo (claro)",
      "fd.themePresetRedDark": "Rojo (oscuro)",
      "fd.themeMenuEdit": "Editar",
      "fd.themeMenuRename": "Renombrar",
